CREATE DATABASE IF NOT EXISTS teleport_scanner CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE teleport_scanner;
CREATE TABLE IF NOT EXISTS sessions (id VARCHAR(64) PRIMARY KEY, username VARCHAR(255) NOT NULL, proxy VARCHAR(255) NOT NULL, tsh_version VARCHAR(10) NOT NULL, cluster VARCHAR(255), logged_in_at DATETIME NOT NULL, expires_at DATETIME, status ENUM('ACTIVE','EXPIRED','LOGGED_OUT') NOT NULL DEFAULT 'ACTIVE', role VARCHAR(16) NOT NULL DEFAULT 'VIEWER', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, timestamp DATETIME NOT NULL, username VARCHAR(255) NOT NULL, role VARCHAR(16) NOT NULL, action VARCHAR(64) NOT NULL, target_type VARCHAR(64), target_count INT NOT NULL DEFAULT 0, job_id VARCHAR(36), result VARCHAR(32) NOT NULL, source_ip VARCHAR(64), details TEXT, INDEX ix_audit_timestamp (timestamp), INDEX ix_audit_username (username));
CREATE TABLE IF NOT EXISTS nodes (id BIGINT AUTO_INCREMENT PRIMARY KEY, session_id VARCHAR(64) NOT NULL, hostname VARCHAR(255) NOT NULL, node_id VARCHAR(255), address VARCHAR(255), cluster VARCHAR(255), labels JSON, teleport_version VARCHAR(100), last_seen DATETIME, last_refresh DATETIME, scan_status ENUM('QUEUED','SCANNING','SAFE','WARNING','ERROR','UNREACHABLE'), last_scan DATETIME, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_session_node(session_id, hostname), CONSTRAINT fk_nodes_session FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS scan_jobs (id CHAR(36) PRIMARY KEY, session_id VARCHAR(64) NOT NULL, start_time DATETIME NOT NULL, end_time DATETIME, total_nodes INT NOT NULL DEFAULT 0, completed_nodes INT NOT NULL DEFAULT 0, safe_nodes INT NOT NULL DEFAULT 0, warning_nodes INT NOT NULL DEFAULT 0, error_nodes INT NOT NULL DEFAULT 0, unreachable_nodes INT NOT NULL DEFAULT 0, status ENUM('PENDING','RUNNING','COMPLETED','CANCELLED','FAILED') NOT NULL DEFAULT 'PENDING', created_by VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_jobs_session FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS scan_results (id BIGINT AUTO_INCREMENT PRIMARY KEY, scan_job_id CHAR(36) NOT NULL, node_id BIGINT, hostname VARCHAR(255) NOT NULL, address VARCHAR(255), status ENUM('SAFE','WARNING','ERROR','UNREACHABLE') NOT NULL, pid INT, ppid INT, username VARCHAR(255), executable TEXT, command_line TEXT, runtime VARCHAR(255), cgroup_path TEXT, risk TEXT, error_message TEXT, scanned_at DATETIME NOT NULL, CONSTRAINT fk_results_job FOREIGN KEY (scan_job_id) REFERENCES scan_jobs(id) ON DELETE CASCADE, INDEX ix_results_job(scan_job_id));
CREATE INDEX ix_scan_results_node_scanned ON scan_results (node_id, scanned_at);
CREATE INDEX ix_scan_jobs_session_start ON scan_jobs (session_id, start_time);
CREATE TABLE IF NOT EXISTS compute_discovery_jobs (id CHAR(36) PRIMARY KEY, session_id VARCHAR(64) NOT NULL, job_name VARCHAR(150) NOT NULL, created_by VARCHAR(255) NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'QUEUED', total_nodes INT NOT NULL DEFAULT 0, completed_nodes INT NOT NULL DEFAULT 0, success_nodes INT NOT NULL DEFAULT 0, failed_nodes INT NOT NULL DEFAULT 0, error_message TEXT, created_at DATETIME NOT NULL, started_at DATETIME, finished_at DATETIME, CONSTRAINT fk_compute_discovery_jobs_session FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE, INDEX ix_compute_discovery_jobs_session_created (session_id, created_at));
CREATE TABLE IF NOT EXISTS compute_discovery_results (id BIGINT AUTO_INCREMENT PRIMARY KEY, job_id CHAR(36) NOT NULL, session_id VARCHAR(64) NOT NULL, node_id BIGINT NOT NULL, hostname VARCHAR(255) NOT NULL, address VARCHAR(255), nic VARCHAR(64), compute VARCHAR(255), status VARCHAR(32) NOT NULL, reason_code VARCHAR(64), reason_message TEXT, detail TEXT, discovered_at DATETIME NOT NULL, CONSTRAINT fk_compute_discovery_results_job FOREIGN KEY (job_id) REFERENCES compute_discovery_jobs(id) ON DELETE CASCADE, CONSTRAINT fk_compute_discovery_results_session FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE, CONSTRAINT fk_compute_discovery_results_node FOREIGN KEY (node_id) REFERENCES nodes(id) ON DELETE CASCADE, INDEX ix_compute_discovery_results_job (job_id), INDEX ix_compute_discovery_results_session_node (session_id, node_id, id), INDEX ix_compute_discovery_results_status_reason (session_id, status, reason_code, discovered_at));
